  j  tile=mat
  k  tile=none object=wall_corner
  l  tile=slab_00 face=SW id=brasa npc=brasa script=brasa
  m  tile=slab_10 face=S gate=yes hide_flag=quiz_d6 id=door6 npc=keydoor text=gym.door
  n  tile=none object=quiz_machine interact=look script=quiz6
  o  tile=slab_00 face=W id=toll6 npc=ladron_s script=toll6
  p  tile=none object=quiz_machine interact=look script=quiz5
  q  tile=slab_11 face=S gate=yes hide_flag=quiz_d5 id=door5 npc=keydoor text=gym.door
  r  tile=slab_01 face=E id=toll5 npc=comefuego_s script=toll5
  s  tile=slab_10 face=S gate=yes hide_flag=quiz_d4 id=door4 npc=keydoor text=gym.door
  t  tile=none object=quiz_machine interact=look script=quiz4
  u  tile=slab_00 face=W id=toll4 npc=cientifico_s script=toll4
  v  tile=none object=quiz_machine interact=look script=quiz3
  w  tile=slab_11 face=S gate=yes hide_flag=quiz_d3 id=door3 npc=keydoor text=gym.door
  x  tile=slab_01 face=E id=toll3 npc=comefuego_s script=toll3
  y  tile=slab_10 face=S gate=yes hide_flag=quiz_d2 id=door2 npc=keydoor text=gym.door
  z  tile=none object=quiz_machine interact=look script=quiz2
  A  tile=slab_00 face=W id=toll2 npc=cientifico_s script=toll2
  B  tile=none object=quiz_machine interact=look script=quiz1
  C  tile=slab_11 face=S gate=yes hide_flag=quiz_d1 id=door1 npc=keydoor text=gym.door
  D  tile=slab_01 face=E id=toll1 npc=comefuego_s script=toll1
