@warp j -> isla_ceniza_sur spawn=gym_door
@script quiz1 interact
    jf quiz_d1 done
    ask gym.q1
    jv 0 1 right
    say gym.wrong
    say tr.comefuego_g1.pre
    battle comefuego_g1 0
    jv 0 1 won
    blackout
    end
  won:
    say gym.won
    jmp open
  right:
    say gym.right
  open:
    sfx door
    setf quiz_d1
    end
  done:
    say gym.off
@end
@script toll1 npc
    jf quiz_d1 done
    say gym.toll.wait
    end
  done:
    say tr.comefuego_g1.after
@end
